const BASE_WEIGHTS = {
  cancel: 20,
  priceProtection: 22,
  preload: 20,
  bonus: 22,
  resale: 16
};
export const platformById = (id) => PLATFORMS.find((p) => p.id === id);
export const regionById = (id) => REGIONS.find((r) => r.id === id);
export const editionById = (id) => EDITIONS.find((e) => e.id === id);
export const channelById = (id) => CHANNELS.find((c) => c.id === id);
export function weightsFor(prefs) {
  const w = { ...BASE_WEIGHTS };
  if (prefs.wantsPreload)
    w.preload += 26;
  if (prefs.wantsCancel)
    w.cancel += 26;
  const total = Object.values(w).reduce((a, b) => a + b, 0);
  return Object.fromEntries(Object.keys(w).map((k) => [k, Math.round(w[k] / total * 1000) / 10]));
}
function adjustedAxes(channel, platform, region, edition) {
  const a = { ...channel.axes };
  if (!channel.physical) {
    a.cancel = clamp(a.cancel + (region.consumerLaw - 5) * 0.6);
  }
  if (!channel.physical) {
    a.preload = clamp(a.preload + (platform.preloadLeadDays >= 7 ? 1 : -0.5));
  }
  if (channel.id === "retailer-code" && platform.preloadLeadDays >= 7) {
    a.preload = clamp(a.preload - 1.5);
  }
  a.bonus = clamp(5 + (a.bonus - 5) * edition.bonusWeight);
  if (channel.physical && !platform.discAvailable)
    a.resale = 0;
  if (channel.physical && (region.id === "in" || region.id === "br")) {
    a.cancel = clamp(a.cancel - 1);
    a.resale = clamp(a.resale - 1);
  }
  return a;
}
const clamp = (n) => Math.max(0, Math.min(10, Math.round(n * 10) / 10));
function timeline(platform, region) {
  return [
    {
      id: "preload",
      label: `${platform.label} preload — completed before launch`,
      when: `Staged about ${platform.preloadLeadDays} days before launch (platform norm)`,
      iso: null,
      detail: platform.preloadNote,
      confidence: "platform-norm"
    },
    {
      id: "cancel-cutoff",
      label: "Praktischer Stornierungs-Stichtag",
      when: "Download start for digital, ship date for physical",
      iso: null,
      detail: `Digitale Bestellungen waren nicht mehr erstattungsfähig, sobald der Download gestartet war. ${region.note}`,
      confidence: "estimated"
    },
    {
      id: "launch",
      label: "Release",
      when: "19. November 2026, Mitternacht ET",
      iso: "2026-11-19",
      detail: "Der Unlock ist weltweit gleichzeitig um 00:00 ET.",
      confidence: "confirmed"
    }
  ];
}
function riskFlags(best, platform, region, edition, prefs) {
  const flags = [];
  if (!best.channel.physical && prefs.wantsCancel) {
    flags.push({
      title: "Dein Erstattungs-Fenster schließt, wenn der Download startet",
      body: `Auf ${platform.label} ist eine digitale Bestellung ab dem Moment, in dem der Download beginnt, nicht mehr erstattungsfähig. Wenn es wichtiger ist, die Option zum Rücktritt zu behalten, als sofort zu spielen, starte den Download nicht.`,
      severity: "high"
    });
  }
  if (best.channel.id === "retailer-code" && prefs.wantsPreload) {
    flags.push({
      title: "Ein später Code kann dich den Sofort-Download kosten",
      body: "Händler-Digital-Codes werden üblicherweise kurz vor dem Release geliefert. Das kann zu wenig Zeit zum Herunterladen lassen, bevor du spielen willst, also lädst du vielleicht am Launch-Tag herunter.",
      severity: "medium"
    });
  }
  if (edition.id !== "standard") {
    flags.push({
      title: `${edition.label}-Boni binden sich an den kaufenden Account`,
      body: `${edition.note} Ein Wechsel von Kanal oder Plattform nach der Bestellung bedeutet, den Bonus-Stack neu zu kaufen, also entscheide die Plattform vor der Edition.`,
      severity: "low"
    });
  }
  if (region.consumerLaw >= 8 && !best.channel.physical) {
    flags.push({
      title: "Du hast ein gesetzliches Widerrufsrecht, nutze es vor dem Download",
      body: `${region.note} Dieses Recht überlebt normalerweise nur, solange der digitale Inhalt nicht heruntergeladen ist, derselbe Stichtag, den der Store anwendet.`,
      severity: "low"
    });
  }
  return flags;
}
export function rankChannels(input) {
  const platform = platformById(input.platform) ?? PLATFORMS[0];
  const region = regionById(input.region) ?? REGIONS[0];
  const edition = editionById(input.edition) ?? EDITIONS[0];
  const prefs = input.prefs;
  const weights = weightsFor(prefs);
  const ranked = CHANNELS.filter((c) => c.platforms.includes(platform.id) && (!c.editions || c.editions.includes(edition.id))).map((channel) => {
    const adj = adjustedAxes(channel, platform, region, edition);
    const axes = Object.keys(AXIS_LABELS).map((id) => ({
      id,
      label: AXIS_LABELS[id],
      raw: adj[id],
      weight: weights[id],
      detail: AXIS_DETAIL[id]
    }));
    const score = Math.round(axes.reduce((sum, a) => sum + a.raw / 10 * a.weight, 0) * 10) / 10;
    const sorted = [...axes].sort((a, b) => b.raw - a.raw);
    return {
      channel,
      score,
      axes,
      strengths: sorted.slice(0, 2).filter((a) => a.raw >= 6).map((a) => a.label),
      risks: sorted.slice(-2).filter((a) => a.raw <= 4).map((a) => a.label),
      confidence: channel.confidence
    };
  }).sort((a, b) => b.score - a.score || a.channel.label.localeCompare(b.channel.label));
  const best = ranked[0];
  const runnerUp = ranked[1];
  const wanted = [
    prefs.wantsPreload ? "sofort beim Unlock spielen" : null,
    prefs.wantsCancel ? "keeping the option to cancel" : null
  ].filter(Boolean);
  const priorities = wanted.length === 0 ? "keine starke Präferenz außer Wert" : wanted.length === 1 ? wanted[0] : `${wanted.slice(0, -1).join(", ")} und ${wanted.at(-1)}`;
  const headline = `${best.channel.short} auf ${platform.label}`;
  const reason = `Weil du uns gesagt hast, dass ${priorities} zählt, erzielt ${best.channel.label.toLowerCase()} ${best.score} von 100 für eine ${edition.label}-Bestellung in ${region.label}, führend bei ${best.strengths.join(" und ").toLowerCase() || "Gesamt-Balance"}${runnerUp ? `, vor ${runnerUp.channel.short.toLowerCase()} mit ${runnerUp.score}` : ""}.`;
  return {
    platform,
    region,
    edition,
    prefs,
    weights,
    ranked,
    best,
    runnerUp,
    headline,
    reason,
    riskFlags: riskFlags(best, platform, region, edition, prefs),
    timeline: timeline(platform, region)
  };
}
